import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

// Books live in a single JSON file. The whole file is loaded once, kept in
// memory, and rewritten after every change.
export async function createStore(filePath) {
  let books = await load(filePath);
  // Chain writes so two requests can't interleave and clobber the file.
  let pending = Promise.resolve();

  function save() {
    const snapshot = JSON.stringify(books, null, 2) + '\n';
    pending = pending.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, filePath);
    });
    return pending;
  }

  return {
    list() {
      return books.slice();
    },

    get(id) {
      return books.find((book) => book.id === id);
    },

    async add({ title, author, notes = '' }) {
      const book = {
        id: newId(),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (book.status !== 'finished') {
        book.status = 'finished';
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

async function load(filePath) {
  let text;
  try {
    text = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  const data = JSON.parse(text);
  if (!Array.isArray(data)) {
    throw new Error(`${filePath} should contain a JSON array of books`);
  }
  return data;
}

// Short, URL-safe and hard to guess, so a shared link only reveals that book.
function newId() {
  return randomBytes(6).toString('base64url');
}

