export function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .error { color: #b00020; }
  form.stack { display: grid; gap: .75rem; }
  label { display: grid; gap: .25rem; }
  input, textarea { font: inherit; padding: .4rem; }
  textarea { min-height: 6rem; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book) {
  return `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish">
  <button type="submit">Mark finished</button>
</form>`;
}

function bookLink(book) {
  return `<a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
    <span class="muted">by ${escapeHtml(book.author)}</span>`;
}

export function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const readingList = reading.length
    ? `<ul>${reading
        .map((b) => `<li><span>${bookLink(b)}</span>${finishButton(b)}</li>`)
        .join('')}</ul>`
    : '<p class="muted">Nothing on the go right now.</p>';

  const finishedList = finished.length
    ? `<ul>${finished
        .map(
          (b) =>
            `<li><span>${bookLink(b)}</span><span class="muted">${formatDate(b.finishedAt)}</span></li>`
        )
        .join('')}</ul>`
    : '<p class="muted">No finished books yet.</p>';

  return layout(
    'My books',
    `<h2>Currently reading</h2>
${readingList}
<h2>Finished</h2>
${finishedList}
<h2>Add a book</h2>
${error ? `<p class="error">${escapeHtml(error)}</p>` : ''}
<form class="stack" method="post" action="/books">
  <label>Title <input name="title" required value="${escapeHtml(values.title ?? '')}"></label>
  <label>Author <input name="author" required value="${escapeHtml(values.author ?? '')}"></label>
  <label>Notes <textarea name="notes">${escapeHtml(values.notes ?? '')}</textarea></label>
  <div><button type="submit">Add book</button></div>
</form>`
  );
}

export function bookPage(book) {
  const status =
    book.status === 'finished'
      ? `<p class="muted">Finished ${formatDate(book.finishedAt)}</p>`
      : `<p class="muted">Currently reading</p>${finishButton(book)}`;

  return layout(
    `${book.title} by ${book.author}`,
    `<h2>${escapeHtml(book.title)}</h2>
<p>by ${escapeHtml(book.author)}</p>
${status}
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escapeHtml(book.notes)}</div>` : '<p class="muted">No notes.</p>'}
<p><a href="/">&larr; All books</a></p>`
  );
}

export function notFoundPage() {
  return layout('Not found', `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

function formatDate(iso) {
  return escapeHtml(
    new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
  );
}

