import { bookPage, homePage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 100_000;

export function createApp(store) {
  return async function handle(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      if (err.statusCode === 413) {
        send(res, 413, 'text/plain; charset=utf-8', 'Request too large');
        return;
      }
      console.error(err);
      if (!res.headersSent) send(res, 500, 'text/plain; charset=utf-8', 'Something went wrong');
      else res.end();
    }
  };
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const method = req.method;

  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET, HEAD');
    return html(res, 200, homePage(store.list()));
  }

  if (pathname === '/books') {
    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    const values = {
      title: (form.get('title') ?? '').trim(),
      author: (form.get('author') ?? '').trim(),
      notes: (form.get('notes') ?? '').trim(),
    };
    if (!values.title || !values.author) {
      return html(res, 400, homePage(store.list(), { error: 'Title and author are both needed.', values }));
    }
    const book = await store.add(values);
    return redirect(res, `/books/${encodeURIComponent(book.id)}`);
  }

  const match = pathname.match(/^\/books\/([^/]+)(\/finish)?$/);
  if (match) {
    const id = decodeURIComponent(match[1]);
    if (match[2]) {
      if (method !== 'POST') return methodNotAllowed(res, 'POST');
      const book = await store.finish(id);
      if (!book) return html(res, 404, notFoundPage());
      // Go back to wherever the button was pressed (list or book page).
      return redirect(res, sameOriginReferer(req) ?? `/books/${encodeURIComponent(id)}`);
    }
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET, HEAD');
    const book = store.get(id);
    if (!book) return html(res, 404, notFoundPage());
    return html(res, 200, bookPage(book));
  }

  return html(res, 404, notFoundPage());
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        req.destroy();
        reject(Object.assign(new Error('Body too large'), { statusCode: 413 }));
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(new URLSearchParams(Buffer.concat(chunks).toString('utf8'))));
    req.on('error', reject);
  });
}

function sameOriginReferer(req) {
  const referer = req.headers.referer;
  if (!referer || !req.headers.host) return null;
  try {
    const url = new URL(referer);
    if (url.host !== req.headers.host) return null;
    return url.pathname + url.search;
  } catch {
    return null;
  }
}

function html(res, status, body) {
  send(res, status, 'text/html; charset=utf-8', body);
}

function send(res, status, type, body) {
  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function methodNotAllowed(res, allow) {
  res.setHeader('Allow', allow);
  send(res, 405, 'text/plain; charset=utf-8', 'Method not allowed');
}

