import { createServer } from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { createStore } from '../src/store.js';

let dir;
let dataFile;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'nested', 'books.json');
});

afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
});

describe('store', () => {
  it('starts empty when the file does not exist', async () => {
    const store = await createStore(dataFile);
    expect(store.list()).toEqual([]);
  });

  it('keeps books after a restart', async () => {
    const store = await createStore(dataFile);
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice' });
    await store.finish(book.id);

    const reopened = await createStore(dataFile);
    expect(reopened.get(book.id)).toMatchObject({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Spice',
